import{_ as n,C as a,o as s,c as o,E as t,a2 as l}from"./chunks/framework.Bx6eOp9J.js";const d="/joinwell52/assets/execution-boundaries-20261028/missing-page-still-readable.figure.en.svg",v=JSON.parse('{"title":"A page is missing from the AI work log. Can it still resume?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"A page is missing from the AI work log. Can it still resume?","date":"2026-10-28","published_date":"2026-10-28","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"A page is missing from the AI work log. Can it still resume?","summary":"Delete an event in the middle and the survivors can still be read, while their original sequence retains a gap. Resumable is not the same as complete.","cover":"/assets/execution-boundaries-20261028/missing-page-still-readable.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Pinned source; upstream before-and-after replay and independent local file probe","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-10-28-missing-page-still-readable.md","filePath":"en/research/2026-10-28-missing-page-still-readable.md","lastUpdated":1793175681000}'),c={name:"en/research/2026-10-28-missing-page-still-readable.md"};function h(g,e,p,m,u,f){const r=a("ArticleCover"),i=a("ArticleTableScroll");return s(),o("div",null,[t(r,{image:"/assets/execution-boundaries-20261028/missing-page-still-readable.cover-v1.png",kicker:"Open-source engineering · Controlled comparison",title:"A page is missing from the AI work log. Can it still resume?",summary:"Delete an event in the middle and the survivors can still be read, while their original sequence retains a gap. Resumable is not the same as complete.",version:"2026-10-28",languageHref:"/zh/research/2026-10-28-missing-page-still-readable",languageLabel:"中文"}),t(i,{language:"en"}),e[0]||(e[0]=l('<h1 id="a-page-is-missing-from-the-ai-work-log-can-it-still-resume" tabindex="-1">A page is missing from the AI work log. Can it still resume? <a class="header-anchor" href="#a-page-is-missing-from-the-ai-work-log-can-it-still-resume" aria-label="Permalink to &quot;A page is missing from the AI work log. Can it still resume?&quot;">​</a></h1><p>Suppose a work journal has four pages and the second page disappears. You would want to read pages three and four to learn what was completed. You would also want to know a page is missing.</p><p>A long-running AI assistant faces the same problem when it restores context from an event log. If the reader stops at the first missing file, later valid records disappear too. If it silently renumbers the survivors into a neat sequence, someone may conclude that the history was complete.</p><h2 id="why-we-investigated-this-change" tabindex="-1">Why we investigated this change <a class="header-anchor" href="#why-we-investigated-this-change" aria-label="Permalink to &quot;Why we investigated this change&quot;">​</a></h2><p>In the <a href="https://joinwell52-ai.github.io/joinwell52/en/runtime/daily-intelligence/2026-10-28" target="_blank" rel="noreferrer">October 28 engineering digest</a>, <a href="https://github.com/OpenHands/software-agent-sdk/pull/6197" target="_blank" rel="noreferrer">OpenHands SDK PR #6197</a> addresses loading after an event file is lost. We wanted to check two properties together: <strong>can the remaining events be read, and can the missing event still be recognized?</strong></p><p>The case is easy to control: write four events, delete a file in the middle, and reload. We first replayed the upstream <code>InMemoryFileStore</code> regressions against both revisions. We then deleted a real local file ourselves and compared two read interfaces. Neither experiment involved a real conversation.</p><h2 id="where-do-the-later-pages-go" tabindex="-1">Where do the later pages go? <a class="header-anchor" href="#where-do-the-later-pages-go" aria-label="Permalink to &quot;Where do the later pages go?&quot;">​</a></h2><p>We pinned the pre-fix source at <a href="https://github.com/OpenHands/software-agent-sdk/tree/acd96e6fa424c02432304395b9208f99be24b54d" target="_blank" rel="noreferrer"><code>acd96e6f</code></a> and the merge commit at <a href="https://github.com/OpenHands/software-agent-sdk/tree/ded5fa5e76ff9b7b4ff622a8df2ed20335e10652" target="_blank" rel="noreferrer"><code>ded5fa5e</code></a>. Five parameterized cases cover a lost middle or first file, sequence reuse, a missing parent event, and repeated warnings.</p><table tabindex="0"><thead><tr><th>Source</th><th>Five cases</th><th>Observed difference</th></tr></thead><tbody><tr><td>Before the fix</td><td><strong>5/5 failed</strong></td><td>After a missing middle file, later surviving events were not indexed; a parent-chain lookup also failed.</td></tr><tr><td>Merge commit</td><td><strong>5/5 passed</strong></td><td>Survivors remained readable, the original gap was preserved and reported, and new events did not reuse old sequence numbers.</td></tr></tbody></table><p>The four-event example makes this concrete. Original on-disk sequence numbers are <code>0, 1, 2, 3</code>. Remove <code>1</code>, and the three readable records can be displayed at dense positions <code>0, 1, 2</code>; their original sequence remains <code>0, 2, 3</code>. The next event receives <code>4</code>, rather than filling the old <code>1</code> slot. A convenient display position no longer pretends to be original history.</p><p><img src="'+d+'" alt="After one event is lost, survivors remain readable while the original sequence retains a gap"></p><p><em>Figure: sequence behavior in the controlled test. The missing content was not recovered.</em></p><p>In another case, a surviving event points to a missing parent. The fixed reader can bridge the visible path back to an earlier surviving event and warn about the gap; it does not repeat the same warning on every traversal. <strong>The path is repaired for use; the missing fact is not restored.</strong></p><h2 id="we-deleted-a-real-local-file-too" tabindex="-1">We deleted a real local file too <a class="header-anchor" href="#we-deleted-a-real-local-file-too" aria-label="Permalink to &quot;We deleted a real local file too&quot;">​</a></h2><p>To go beyond the upstream in-memory test, we used the merge commit&#39;s original <code>EventLog</code> and <code>LocalFileStore</code> to write four JSON event files in a temporary directory. We deleted sequence 1 and reloaded through a new store instance. All three survivors remained readable. <strong>Ordinary iteration showed consecutive list positions <code>0,1,2</code>; reading durable sequence numbers separately showed <code>0,2,3</code>.</strong> Loading also logged the missing file. The <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-10-28-execution-boundaries" target="_blank" rel="noreferrer">script, event IDs, and both sequences</a> are available for inspection.</p><p>That split is the point of the story. “Can I read it?” is answered by one interface. “Is it complete?” requires another interface or the warning. We have not shown that a higher-level agent ignores this information. We have shown that a consumer of the ordinary list alone cannot see the gap in its list positions.</p><h2 id="resumability-and-completeness-are-different-claims" tabindex="-1">Resumability and completeness are different claims <a class="header-anchor" href="#resumability-and-completeness-are-different-claims" aria-label="Permalink to &quot;Resumability and completeness are different claims&quot;">​</a></h2><p>Our observation is deliberately narrow. In both the upstream simulated gaps and our local file deletion, the fixed version kept survivors readable and preserved the gap in durable sequence numbers and logs. It does not prove recovery of damaged content or behavior under production disk failure, concurrent writers, or every packaged release. The PR is merged; we did not verify a specific release.</p><p>This raises a harder question for long-running agents: when history has a hole, does the layer that verifies the work receive a clear “evidence incomplete” signal? If it sees only the ordinary list, it may mistake recovery for completeness. Our tests did <strong>not</strong> evaluate that higher-level propagation; it is the next experiment suggested by the two read views.</p><p>Users can weigh in too: when a log is damaged, would you prefer an assistant to stop immediately, or show what can be recovered while clearly marking the missing position? The appropriate response depends on the task, but the missing fact should remain visible.</p><p>The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-10-28-execution-boundaries/00-report.en.md" target="_blank" rel="noreferrer">public experiment report</a> records pinned versions, the independent disk probe, commands, and limits. This round combines an upstream before-and-after replay with local file deletion, not a production data-loss incident. <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',21))])}const w=n(c,[["render",h]]);export{v as __pageData,w as default};
